#!/usr/bin/env python3
"""Install advanced report editor and per-company document dispatch from an immutable source bundle."""
import base64, gzip, hashlib, io, os, runpy, sys, tarfile
from pathlib import Path
BUNDLE=""
EXPECTED_SHA256="cc9fad134e050270a64dcd023110fd37c300701dff1e494bac8bd4ab0d9dfa55"
def main():
    app=Path(sys.argv[1]); platform=sys.argv[2]
    if platform not in ("windows","android"): raise SystemExit("Invalid platform")
    raw=base64.b64decode(BUNDLE,validate=True)
    if hashlib.sha256(raw).hexdigest()!=EXPECTED_SHA256: raise SystemExit("Bundle integrity failure")
    repo=Path(__file__).resolve().parent.parent
    with tarfile.open(fileobj=io.BytesIO(gzip.decompress(raw))) as archive:
        for member in archive:
            name=member.name
            if not member.isfile() or not (name.startswith("tools/") or name.startswith("build_sources/")) or ".." in Path(name).parts:
                raise SystemExit("Invalid bundle path: "+name)
            target=repo/name
            target.parent.mkdir(parents=True,exist_ok=True)
            with archive.extractfile(member) as src: target.write_bytes(src.read())
    # Compatibility with Flutter FilledButton.icon: it uses label, not child.
    dispatch_patch=repo/"tools/patch_document_dispatch_v329116.py"
    body=dispatch_patch.read_text(encoding="utf-8")
    wrong="icon: const Icon(Icons.mark_email_read_outlined), child: const Text('Enviar por e-mail')"
    assert body.count(wrong)==1, "Unexpected Ronda action source"
    dispatch_patch.write_text(body.replace(wrong,
        "icon: const Icon(Icons.mark_email_read_outlined), label: const Text('Enviar por e-mail')",1),
        encoding="utf-8",newline="\n")
    # Windows Python defaults to cp1252: keep regression reads explicitly UTF-8.
    regression=repo/"tools/regression_document_dispatch_v329116.py"
    checks=regression.read_text(encoding="utf-8")
    assert checks.count(".read_text()")>=5, "Unrecognized document regression source"
    regression.write_text(checks.replace(".read_text()", '.read_text(encoding="utf-8")'),
        encoding="utf-8",newline="\n")
    def run(name,*args):
        old=sys.argv
        try:
            sys.argv=[str(repo/"tools"/name),*map(str,args)]
            runpy.run_path(sys.argv[0],run_name="__main__")
        finally: sys.argv=old
    run("patch_report_editor_v329115.py",app,platform)
    run("regression_report_editor_v329115.py",app,
        "3.29.115+257" if platform=="android" else "3.30.39+227")
    run("patch_document_dispatch_v329116.py",app,platform)
    run("regression_document_dispatch_v329116.py",app,
        "3.29.116+258" if platform=="android" else "3.30.40+228")
    print("AUDITAR_REPORT_EDITOR_DOCUMENT_CENTER_BUNDLE_OK",platform)
if __name__=="__main__":main()
